package cn.musicsquare.app;
import org.json.*;import org.junit.Test;import static org.junit.Assert.*;import java.util.concurrent.atomic.AtomicInteger;
public class PlaybackCacheTest{
 static class Memory implements PlaybackCache.Store{String value="{}";public String read(){return value;}public void write(String s){value=s;}}
 JSONObject track()throws Exception{return MusicApi.base("netease","123","原歌曲","歌手").put("durationMs",200000);}
 JSONObject playable()throws Exception{return track().put("audioUrl","https://m8.music.126.net/a.mp3").put("playbackProvider","wzapi");}
 @Test public void hitsPersistedCacheWithoutResolver()throws Exception{Memory s=new Memory();long[] now={1000};PlaybackCache a=new PlaybackCache(s,()->now[0],t->{throw new AssertionError();});a.put(playable());PlaybackCache b=new PlaybackCache(s,()->now[0],t->{throw new AssertionError();});JSONObject r=b.resolve(track().put("title","新标题"),false);assertTrue(r.getBoolean("audioFromCache"));assertEquals("新标题",r.getString("title"));assertEquals("https://m8.music.126.net/a.mp3",r.getString("audioUrl"));}
 @Test public void expiresAndDoesNotReuseInvalidatedLink()throws Exception{Memory s=new Memory();long[] now={1000};PlaybackCache c=new PlaybackCache(s,()->now[0],t->t);c.put(playable());now[0]+=11*60000;assertNull(c.get(track()));c.put(playable());c.invalidate(track());assertNull(c.get(track()));}
 @Test public void thirtyMinutePreviewMemoryPersistsAndExpires()throws Exception{Memory s=new Memory();long[] now={1000};PlaybackCache a=new PlaybackCache(s,()->now[0],t->t);a.put(playable());a.markPreview(track());assertNull(a.get(track()));PlaybackCache b=new PlaybackCache(s,()->now[0],t->t);assertTrue(b.recentPreview(track()));now[0]+=31*60000;assertFalse(b.recentPreview(track()));}
 @Test public void ignoresTrialAndLocalTracks()throws Exception{PlaybackCache c=new PlaybackCache(new Memory(),()->1000,t->t);c.put(playable().put("trial",true));assertNull(c.get(track()));JSONObject local=MusicApi.base("local","file1","本地","作者").put("audioUrl","content://audio/1");assertSame(local,c.resolve(local,false));}
 @Test public void forceRefreshInvokesSourceOnce()throws Exception{Memory s=new Memory();AtomicInteger calls=new AtomicInteger();PlaybackCache c=new PlaybackCache(s,()->1000,t->{calls.incrementAndGet();return new JSONObject(t.toString()).put("audioUrl","https://qqmusic.qq.com/new.mp3");});JSONObject t=MusicApi.base("qq","mid","歌","手");c.put(new JSONObject(t.toString()).put("audioUrl","https://qqmusic.qq.com/old.mp3"));assertEquals(0,calls.get());assertTrue(c.resolve(t,false).getBoolean("audioFromCache"));assertFalse(c.resolve(t,true).getBoolean("audioFromCache"));assertEquals(1,calls.get());assertTrue(c.get(t).getString("audioUrl").contains("new"));}
 @Test public void signedNeteaseUrlExpiresBeforeDefaultTtl()throws Exception{long now=java.time.Instant.parse("2026-11-14T12:00:00Z").toEpochMilli();PlaybackCache c=new PlaybackCache(new Memory(),()->now,t->t);c.put(playable().put("audioUrl","https://m8.music.126.net/20261114200010/key/a.mp3"));assertNull(c.get(track()));}
 @Test public void recentPreviewSkipsOfficialButNetworkErrorDoesNotCreateMemory()throws Exception{AtomicInteger count=new AtomicInteger();JSONObject payload=new JSONObject().put("success",true).put("id",123).put("song",new JSONObject().put("id",123).put("duration_ms",200000)).put("levels",new JSONArray().put(new JSONObject().put("level","standard").put("url","https://m8.music.126.net/a.mp3")));JSONObject r=new NeteaseResolver(u->{count.incrementAndGet();assertTrue(u.startsWith("https://wzapi.com/"));return payload.toString();},t->true,t->{throw new AssertionError();}).resolve(track());assertEquals("wzapi",r.getString("playbackProvider"));assertEquals(1,count.get());}
 @Test public void cacheBoundedAcrossManyTracks()throws Exception{Memory s=new Memory();PlaybackCache c=new PlaybackCache(s,()->1000,t->t);for(int i=0;i<100;i++)c.put(playable().put("songid",String.valueOf(i)));assertTrue(new JSONObject(s.value).getJSONObject("urls").length()<=80);}
}
